['RouteSegment]:\n    "', '\n    Convert CPP solution to RouteSegment list for GPX export.\n    \n    Args:\n        G: NetworkX graph with node coordinates in node attributes (lat, lon)\n        route_nodes: List of nodes in the Eulerian circuit\n        \n    Returns:\n        List of RouteSegment objects for GPX export\n    "', '\n    if not GPX_EXPORT_AVAILABLE:\n        return []\n        \n    if not route_nodes:\n        return []\n        \n    # Create waypoints for each unique node\n    waypoints = []\n    added_nodes = set()\n    \n    for node in route_nodes:\n        if node not in added_nodes:\n            # Get node coordinates from graph\n            ndata = G.nodes[node]\n            lat = ndata.get("lat', 0, 'lon = ndata.get("lon', 0, 'waypoints.append(Waypoint(lat, lon, name=f"Node {node}', 'added_nodes.add(node)\n    \n    # Create track points from the route\n    track = []\n    for node in route_nodes:\n        # Get node coordinates from graph\n        ndata = G.nodes[node]\n        lat = ndata.get("lat', 0, 'lon = ndata.get("lon', 0, 'track.append((lat, lon))\n    \n    # Create a single route segment for the entire Eulerian circuit\n    segment = RouteSegment(\n        track=track,\n        waypoints=waypoints,\n        name="Eulerian Circuit', 'return [segment]\n\ndef export_cpp_solution_to_gpx(G, route_nodes: List, instance_name: str = "CPP_Solution") -> str:\n    "', '\n    Export a CPP solution to GPX format.\n    \n    Args:\n        G: NetworkX graph with node coordinates in node attributes (lat, lon)\n        route_nodes: List of nodes in the Eulerian circuit\n        instance_name: Name of the problem instance\n        \n    Returns:\n        GPX XML string or None if export failed\n    "', '\n    if not GPX_EXPORT_AVAILABLE:\n        return None\n        \n    try:\n        segments = cpp_solution_to_gpx_segments(G, route_nodes)\n        if not segments:\n            return None\n            \n        gpx_str = build_gpx(\n            segments,\n            creator=f"CPP Solution Exporter', 'waypoints_only_from_tracks=False\n        )\n        return gpx_str\n    except Exception as e:\n        print(f"Warning: Failed to export {instance_name} CPP solution to GPX: {e}', 'file=sys.stderr)\n        return None']